package com.transiva.app;
import android.app.Activity;import android.graphics.drawable.Animatable;import android.graphics.drawable.Drawable;import android.widget.Button;import android.widget.ProgressBar;import java.util.Locale;
final class MerchantUiHelpers{private MerchantUiHelpers(){}static void setButtonLoading(Activity a,Button b,boolean loading,String normal,String loadingText){if(b==null)return;b.setEnabled(!loading);if(!loading){b.setText(normal);b.setCompoundDrawables(null,null,null,null);b.setCompoundDrawablePadding(0);return;}b.setText(loadingText);ProgressBar p=new ProgressBar(a);Drawable d=p.getIndeterminateDrawable();if(d!=null){try{d.setTint(b.getCurrentTextColor());}catch(Exception ignored){}int size=(int)(18*a.getResources().getDisplayMetrics().density+.5f);d.setBounds(0,0,size,size);b.setCompoundDrawables(d,null,null,null);b.setCompoundDrawablePadding((int)(8*a.getResources().getDisplayMetrics().density+.5f));if(d instanceof Animatable)((Animatable)d).start();}}static String humanBytes(long bytes){if(bytes<=0)return "0 KB";if(bytes<1024L*1024L)return Math.max(1,Math.round(bytes/1024f))+" KB";return String.format(Locale.US,"%.1f MB",bytes/(1024f*1024f));}}
